1	/**
2	 * Exhaustive role×action sweep of `ROLE_MATRIX`, including ownership
3	 * escalations and the cross-tenant denial.
4	 */
5	import { describe, expect, it } from "vitest";
6	import { ROLE_MATRIX, can, canAll, explain } from "@/lib/permissions";
7	import type { IssueId, ProjectId } from "@/types/common";
8	import { ROLES, ROLE_RANK, type Role } from "@/types/member";
9	import type { PermissionAction, PermissionResource } from "@/types/permission";
10	import { ALICE, BOB, ORG_A, ORG_B, makeActor } from "../helpers/factories";
11	
12	const ACTIONS = Object.keys(ROLE_MATRIX) as readonly PermissionAction[];
13	
14	/**
15	 * A resource in ORG_A owned by nobody the actor is, so the sweep measures the
16	 * matrix alone and never trips an ownership escalation.
17	 */
18	const foreignOwned: PermissionResource = {
19	  kind: "issue",
20	  orgId: ORG_A,
21	  projectId: "01HZZZPPPPPPPPPPPPPPPPPPPP" as ProjectId,
22	  issueId: "01HZZZSSSSSSSSSSSSSSSSSSSS" as IssueId,
23	  authorId: BOB,
24	  assigneeId: BOB,
25	};
26	
27	const orgResource: PermissionResource = { kind: "organization", orgId: ORG_A };
28	
29	describe("permissions matrix", () => {
30	  it("covers every declared action", () => {
31	    expect(ACTIONS.length).toBeGreaterThan(20);
32	    for (const action of ACTIONS) {
33	      expect(ROLES).toContain(ROLE_MATRIX[action]);
34	    }
35	  });
36	
37	  it("grants exactly the roles at or above the required rank", () => {
38	    for (const action of ACTIONS) {
39	      const required = ROLE_MATRIX[action];
40	      for (const role of ROLES) {
41	        const expected = ROLE_RANK[role] >= ROLE_RANK[required];
42	        expect(
43	          can(makeActor({ role, userId: ALICE }), action, foreignOwned),
44	          `${role} → ${action}`,
45	        ).toBe(expected);
46	      }
47	    }
48	  });
49	
50	  it("reports `granted_by_role` and `denied_by_role` as the reason", () => {
51	    expect(explain(makeActor({ role: "owner" }), "org:delete", orgResource).reason).toBe(
52	      "granted_by_role",
53	    );
54	    expect(explain(makeActor({ role: "admin" }), "org:delete", orgResource).reason).toBe(
55	      "denied_by_role",
56	    );
57	  });
58	
59	  it("denies every action across a tenant boundary, whatever the role", () => {
60	    for (const role of ROLES) {
61	      const foreign = makeActor({ role, orgId: ORG_B });
62	      for (const action of ACTIONS) {
63	        expect(can(foreign, action, orgResource), `${role} → ${action}`).toBe(false);
64	      }
65	    }
66	    expect(explain(makeActor({ orgId: ORG_B }), "org:read", orgResource).reason).toBe(
67	      "denied_cross_tenant",
68	    );
69	  });
70	
71	  it("checks the tenant boundary before the staff bypass", () => {
72	    const staff = makeActor({ orgId: ORG_B, isPlatformStaff: true, role: "owner" });
73	    expect(can(staff, "org:read", orgResource)).toBe(false);
74	    expect(explain(staff, "org:read", orgResource).reason).toBe("denied_cross_tenant");
75	  });
76	
77	  it("lets platform staff bypass the matrix inside their own tenant", () => {
78	    const staff = makeActor({ role: "viewer", isPlatformStaff: true });
79	    for (const action of ACTIONS) {
80	      expect(can(staff, action, orgResource), action).toBe(true);
81	    }
82	    expect(explain(staff, "org:delete", orgResource).reason).toBe("granted_by_staff");
83	  });
84	
85	  it("puts billing and deletion behind the owner role alone", () => {
86	    for (const action of ["org:delete", "org:manage_billing", "project:delete"] as const) {
87	      expect(ROLE_MATRIX[action]).toBe("owner");
88	      expect(can(makeActor({ role: "admin" }), action, orgResource)).toBe(false);
89	      expect(can(makeActor({ role: "owner" }), action, orgResource)).toBe(true);
90	    }
91	  });
92	
93	  it("keeps the everyday read actions available to a viewer", () => {
94	    for (const action of [
95	      "org:read",
96	      "member:read",
97	      "project:read",
98	      "issue:read",
99	      "comment:read",
100	      "notification:read",
101	    ] as const) {
102	      expect(ROLE_MATRIX[action], action).toBe("viewer");
103	      expect(can(makeActor({ role: "viewer" }), action, orgResource), action).toBe(true);
104	    }
105	  });
106	
107	  it("holds the audit trail above viewer, unlike the other reads", () => {
108	    expect(ROLE_MATRIX["activity:read"]).toBe("member");
109	    expect(can(makeActor({ role: "viewer" }), "activity:read", orgResource)).toBe(false);
110	    expect(can(makeActor({ role: "member" }), "activity:read", orgResource)).toBe(true);
