import { index, sqliteTable, text } from "drizzle-orm/sqlite-core";
import { idColumn, tenantColumns } from "./_shared";

/**
 * Ownership-handover offers. At most one row per org is ever `"pending"` at a
 * time; past offers are kept for history rather than deleted.
 */
export const ownershipHandovers = sqliteTable(
  "ownership_handovers",
  {
    id: idColumn(),
    ...tenantColumns,
    fromUserId: text("from_user_id").notNull(),
    toUserId: text("to_user_id").notNull(),
    status: text("status", {
      enum: ["pending", "accepted", "declined", "canceled", "expired"],
    })
      .notNull()
      .default("pending"),
    expiresAt: text("expires_at").notNull(),
    createdAt: text("created_at").notNull(),
    resolvedAt: text("resolved_at"),
  },
  (table) => [index("ownership_handovers_org_idx").on(table.orgId, table.status)],
);

export type OwnershipHandoverRow = typeof ownershipHandovers.$inferSelect;
export type NewOwnershipHandoverRow = typeof ownershipHandovers.$inferInsert;

