/**
 * Only the *recorded* owner (`org.ownerId`) may offer or withdraw a handover —
 * holding the `owner` role is necessary but not sufficient, since a second
 * member can carry that role without being the one billing and new-member
 * alerts follow.
 */
function assertRecordedOwner(actor: Actor, org: Organization): void {
  assertCan(actor, "org:manage_ownership", orgResource(org.id));

  if (actor.userId !== org.ownerId) {
    throw new PermissionDeniedError("org:manage_ownership", {
      action: "org:manage_ownership",
      resourceKind: "organization",
      allowed: false,
      reason: "denied_by_role",
    });
  }
}

/**
 * Resolves the offer directed at `userId`, or throws the refusal that
 * explains why there is nothing to act on — `"nothing_pending"` for anyone
 * but the offered member (or when nothing is open), `"expired"` for the
 * offered member acting too late.
 */
async function requireHandoverForRecipient(
  orgId: OrgId,
  userId: UserId,
): Promise<OwnershipHandover> {
  const handover = await handoverRepo.findLatestHandover(orgId);

  if (!handover || handover.status !== "pending" || handover.toUserId !== userId) {
    throw new OwnershipHandoverError("nothing_pending");
  }

  if (handover.expiresAt <= toIsoTimestamp(new Date())) {
    await handoverRepo.resolveHandover(orgId, handover.id, "expired", handover.expiresAt);
    throw new OwnershipHandoverError("expired");
  }

  return handover;
}

/**
 * Offers the workspace to `toUserId`. Refused unless the actor is the
 * recorded owner, the target is an active member other than the owner, and no
 * other offer is currently open.
 */
export async function initiateOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
  toUserId: UserId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);

  const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
  assertRecordedOwner(actor, org);

  if (toUserId === org.ownerId) {
    throw new OwnershipHandoverError("self");
  }

  const target = await memberRepo.findMember(orgId, toUserId);
  if (!target || target.status !== "active") {
    throw new NotFoundError("Member", toUserId);
  }

  const open = await handoverRepo.findOpenHandover(orgId);
  if (open) {
    throw new OwnershipHandoverError("pending_exists");
  }

  const handover = await handoverRepo.insertHandover(orgId, actor.userId, toUserId);

  await notify(orgId, "ownership_handover", [toUserId], {
    title: "You've been offered ownership of this workspace",
    body: `${actor.userId} offered you ownership of this workspace`,
    href: "/settings/members",
    actorId: actor.userId,
  });

  return handover;
}

/** The open offer for `orgId`, or `null`. Visible to any active member. */
export async function getPendingOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));

  return handoverRepo.findOpenHandover(orgId);
}

/**
 * Accepts the open offer directed at the actor. The actor becomes the
 * recorded owner and holds the `owner` role; the previous owner steps down to
 * `admin` if they still held `owner`. Every role change and the transfer
 * itself are published on behalf of the accepting member.
 */
export async function acceptOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<Organization> {
  assertOrgScope(actor, orgId);

  const handover = await requireHandoverForRecipient(orgId, actor.userId);

  const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
  const previousOwnerId = org.ownerId;

  const acceptingMember = requireFound(
    await memberRepo.findMember(orgId, actor.userId),
    "Member",
    actor.userId,
  );

  if (acceptingMember.role !== "owner") {
    const promoted = await memberRepo.updateMemberRole(orgId, acceptingMember.id, "owner");
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: promoted.id,
      from: acceptingMember.role,
      to: promoted.role,
    });
  }

  const previousOwnerMember = await memberRepo.findMember(orgId, previousOwnerId);
  if (previousOwnerMember && previousOwnerMember.role === "owner") {
    const demoted = await memberRepo.updateMemberRole(orgId, previousOwnerMember.id, "admin");
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: demoted.id,
      from: previousOwnerMember.role,
      to: demoted.role,
    });
  }

  const updatedOrg = await orgRepo.updateOwner(orgId, actor.userId);

  await handoverRepo.resolveHandover(
    orgId,
    handover.id,
    "accepted",
    toIsoTimestamp(new Date()),
  );

  await emit("organization.ownership_transferred", {
    ...actorEnvelope(actor),
    fromUserId: previousOwnerId,
    toUserId: actor.userId,
  });

  return updatedOrg;
}

/** Declines the open offer directed at the actor; the owner may offer again. */
export async function declineOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);

  const handover = await requireHandoverForRecipient(orgId, actor.userId);

  return handoverRepo.resolveHandover(
    orgId,
    handover.id,
    "declined",
    toIsoTimestamp(new Date()),
  );
}

/** Withdraws the offer the recorded owner made, while it is still open. */
export async function cancelOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);

  const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
  assertRecordedOwner(actor, org);

  const handover = await handoverRepo.findOpenHandover(orgId);
  if (!handover) {
    throw new OwnershipHandoverError("nothing_pending");
  }

  return handoverRepo.resolveHandover(
    orgId,
    handover.id,
    "canceled",
    toIsoTimestamp(new Date()),
  );
}

