import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { subscribe } from "@/lib/event-bus";
import { OwnershipHandoverError } from "@/lib/errors";
import { PermissionDeniedError } from "@/lib/permissions";
import * as memberRepo from "@/server/repositories/member-repository";
import * as organizationService from "@/server/services/organization-service";
import * as memberService from "@/server/services/member-service";
import { createTenant, useTemporaryDatabase } from "../tests/server/_support/fixtures";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

describe("ownership handover smoke", () => {
  it("full accept flow", async () => {
    const tenant = await createTenant("handover-smoke-1", "growth");

    // admin cannot offer
    await expect(
      organizationService.initiateOwnershipHandover(
        tenant.actors.admin,
        tenant.org.id,
        tenant.userIds.member,
      ),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    // owner offers to member
    const offer = await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.member,
    );
    expect(offer.status).toBe("pending");
    expect(offer.toUserId).toBe(tenant.userIds.member);

    // second offer refused
    await expect(
      organizationService.initiateOwnershipHandover(
        tenant.actors.owner,
        tenant.org.id,
        tenant.userIds.viewer,
      ),
    ).rejects.toMatchObject({ reason: "pending_exists" });

    // wrong person can't accept
    await expect(
      organizationService.acceptOwnershipHandover(tenant.actors.viewer, tenant.org.id),
    ).rejects.toMatchObject({ reason: "nothing_pending" });

    // pending visible
    const pending = await organizationService.getPendingOwnershipHandover(
      tenant.actors.viewer,
      tenant.org.id,
    );
    expect(pending?.toUserId).toBe(tenant.userIds.member);

    const events: unknown[] = [];
    const offRole = subscribe("member.role_changed", (p) => events.push(["role", p]));
    const offTransfer = subscribe("organization.ownership_transferred", (p) =>
      events.push(["transfer", p]),
    );

    const org = await organizationService.acceptOwnershipHandover(
      tenant.actors.member,
