/**
 * Ownership-handover offers. At most one row per org is `"pending"` at a
 * time, so "the open offer" is always the latest row, checked for expiry.
 */
import { desc, eq, and } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, ownershipHandovers } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toOwnershipHandover } from "./_mappers";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import type { OwnershipHandover, OwnershipHandoverStatus } from "@/types/organization";

const HANDOVER_LIFETIME_MS = 7 * 24 * 60 * 60 * 1000;

export async function insertHandover(
  orgId: OrgId,
  fromUserId: UserId,
  toUserId: UserId,
): Promise<OwnershipHandover> {
  const stamp = toIsoTimestamp(new Date());
  const expiresAt = toIsoTimestamp(new Date(Date.now() + HANDOVER_LIFETIME_MS));

  const row = getDb()
    .insert(ownershipHandovers)
    .values({
      id: newId(),
      orgId,
      fromUserId,
      toUserId,
      status: "pending",
      expiresAt,
      createdAt: stamp,
      resolvedAt: null,
    })
    .returning()
    .get();

  return toOwnershipHandover(row);
}

/** The most recent offer for the org, whatever its status. */
export async function findLatestHandover(
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  const row = getDb()
    .select()
    .from(ownershipHandovers)
    .where(orgPredicate(ownershipHandovers.orgId, orgId))
    .orderBy(desc(ownershipHandovers.createdAt), desc(ownershipHandovers.id))
    .get();

  return row ? toOwnershipHandover(row) : null;
}

/**
 * The open offer, or `null`. A pending offer past its `expiresAt` is lazily
 * flipped to `"expired"` here — nothing else reads this table on a schedule.
 */
export async function findOpenHandover(
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  const latest = await findLatestHandover(orgId);
  if (!latest || latest.status !== "pending") return null;

  if (latest.expiresAt <= toIsoTimestamp(new Date())) {
    await resolveHandover(orgId, latest.id, "expired", latest.expiresAt);
    return null;
  }

  return latest;
}

export async function resolveHandover(
  orgId: OrgId,
  id: string,
  status: OwnershipHandoverStatus,
  resolvedAt: IsoTimestamp,
): Promise<OwnershipHandover> {
  const row = getDb()
    .update(ownershipHandovers)
    .set({ status, resolvedAt })
    .where(
      and(orgPredicate(ownershipHandovers.orgId, orgId), eq(ownershipHandovers.id, id)),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Ownership handover ${id} not found in org ${orgId}`);
  return toOwnershipHandover(row);
}

/**
 * Auto-withdraws the open offer when either party leaves the workspace.
 * A no-op when no offer is open or the departing member is neither side of it.
 */
export async function withdrawIfPartyLeft(
  orgId: OrgId,
  departedUserId: UserId,
): Promise<void> {
  const open = await findOpenHandover(orgId);
  if (!open) return;
  if (open.fromUserId !== departedUserId && open.toUserId !== departedUserId) return;

  await resolveHandover(orgId, open.id, "canceled", toIsoTimestamp(new Date()));
}

