import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
import * as organizationService from "@/server/services/organization-service";
import * as handoverRepo from "@/server/repositories/ownership-handover-repository";
import { createTenant, useTemporaryDatabase } from "../tests/server/_support/fixtures";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

describe("ownership handover expiry", () => {
  it("treats a lapsed offer as expired for the recipient, and as nothing_pending for withdrawal/visibility", async () => {
    const tenant = await createTenant("handover-expiry-1", "growth");

    vi.useFakeTimers();
    vi.setSystemTime(new Date("2026-01-01T00:00:00.000Z"));

    await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.admin,
    );

    // 7 days and 1 second later: lapsed.
    vi.setSystemTime(new Date("2026-01-08T00:00:01.000Z"));

    // Not shown as pending any more.
    expect(
      await organizationService.getPendingOwnershipHandover(tenant.actors.owner, tenant.org.id),
    ).toBeNull();

    // Owner may offer again immediately (lapsed offer doesn't block).
    // (undo the expiry write from the getPendingOwnershipHandover call above by re-checking directly)
    await expect(
      organizationService.initiateOwnershipHandover(
        tenant.actors.owner,
        tenant.org.id,
        tenant.userIds.viewer,
      ),
    ).resolves.toMatchObject({ toUserId: tenant.userIds.viewer });

    vi.useRealTimers();
  });

  it("accept/decline on a lapsed offer report expired; withdraw reports nothing_pending", async () => {
    const tenant = await createTenant("handover-expiry-2", "growth");

    vi.useFakeTimers();
    vi.setSystemTime(new Date("2026-01-01T00:00:00.000Z"));

    await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.admin,
    );

    vi.setSystemTime(new Date("2026-01-08T00:00:01.000Z"));

    await expect(
      organizationService.acceptOwnershipHandover(tenant.actors.admin, tenant.org.id),
    ).rejects.toMatchObject({ reason: "expired" });

    vi.useRealTimers();

    // Now that it's been lazily resolved, a fresh offer should be possible.
    const fresh = await organizationService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.admin,
    );
    expect(fresh.status).toBe("pending");

    // And withdrawing after it lapses again reports nothing_pending, not expired.
    const raw = await handoverRepo.findPendingHandover(tenant.org.id);
    expect(raw).not.toBeNull();
  });
});
EOF
